// Airtable has no "IN" operator - build an OR() of RECORD_ID() comparisons.
// n8n coerces workflow inputs, so assignmentIds can arrive as a real array,
// a JSON string, or a comma-separated string. Accept all three.
const input = $input.first().json;
const raw = input.assignmentIds;

let ids = [];
if (Array.isArray(raw)) {
  ids = raw;
} else if (typeof raw === "string") {
  const t = raw.trim();
  if (t.startsWith("[")) { try { ids = JSON.parse(t); } catch (e) { ids = []; } }
  else if (t) { ids = t.split(","); }
}
ids = ids.map(x => String(x).trim()).filter(x => x.startsWith("rec"));

const formula = ids.length
  ? "OR(" + ids.map(i => "RECORD_ID()='" + i + "'").join(",") + ")"
  : "RECORD_ID()='none'";

return [{ json: {
  formula,
  changeType: input.changeType || "PUBLISH",
  count: ids.length,
  // diagnostics - makes a bad handoff visible instead of silent
  receivedType: Array.isArray(raw) ? "array" : typeof raw,
  receivedRaw: JSON.stringify(raw === undefined ? null : raw).slice(0, 200),
}}];

// Batch size is 1, so this sees exactly one assignment per pass.
// Contact routing comes off the Assignment row via Lookup fields - no extra Staff fetch.
const one = (v) => Array.isArray(v) ? v[0] : v;
// The Airtable node returns either { id, fields:{...} } or a flattened
// { id, ...fieldValues } depending on node version. Normalise both shapes.
const REC = (j) => (j && j.fields) ? j : { id: j && j.id, fields: j || {} };
const r = REC($input.first().json);
const f = r.fields;
return [{ json: {
  assignmentId: r.id,
  staffId:   one(f['Staff']),
  staffName: one(f['Staff Name']),
  role:      f['Role'],
  client:    one(f['Session Client']),
  date:      one(f['Session Date']),
  startTime: one(f['Session Start']),
  endTime:   one(f['Session End']),
  // routing - these are Lookup fields on Assignments (see schema guide section 6)
  notifyChannel:   one(f['Staff Notify Channel']) || 'Email',
  telegramChatId:  one(f['Staff Telegram Chat ID']) || '',
  slackMemberId:   one(f['Staff Slack Member ID']) || '',
  email:           one(f['Staff Email']) || '',
  changeType: $('Build ID Filter').first().json.changeType,
}}];

const r = $input.first().json;
const d = $('Prepare Message Context').first().json;

let text;
let source = 'groq';
if (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) {
  text = r.choices[0].message.content;
} else {
  source = 'fallback';
  const lead = d.changeType === 'CHANGE'
    ? 'Schedule change: '
    : 'Schedule published: ';
  text = `${lead}you are assigned as ${d.role} for ${d.client} on ${d.date}, ${d.startTime}-${d.endTime}. Please confirm in the group chat.`;
}

return [{ json: Object.assign({}, d, { text, messageSource: source }) }];

// Reach back by node name: this node's INPUT is the Telegram/Slack/Email
// response, which does not carry the assignment context.
const d = $('Message + Fallback').first().json;
return [{ json: {
  id: d.assignmentId,
  fields: {
    'Status': 'Published',
    'Notified': true,
    // baseline for Workflow E's change detection
    'Logged State': JSON.stringify({ staff: d.staffName, role: d.role, status: 'Published' }),
  },
}}];

const d = $('Message + Fallback').first().json;
return [{ json: {
  'Action': d.changeType === 'CHANGE' ? 'ASSIGNMENT_CHANGED' : 'PUBLISHED',
  'Actor': 'Workflow C',
  'Source': 'Automated',
  'Staff Affected': [d.staffId],
  'After Value': `${d.role} - ${d.client} ${d.date} ${d.startTime}-${d.endTime}`,
  'Reason': `Notification sent via ${d.notifyChannel || 'Email'} (message source: ${d.messageSource})`,
}}];

// Runs once after the loop finishes. Produces a printable schedule table.
// The Airtable node returns either { id, fields:{...} } or a flattened
// { id, ...fieldValues } depending on node version. Normalise both shapes.
const REC = (j) => (j && j.fields) ? j : { id: j && j.id, fields: j || {} };
const rows = $('Get Assignments').all().map(i => REC(i.json)).filter(r => r && r.id);
const one = (v) => Array.isArray(v) ? v[0] : v;

const byDate = {};
for (const r of rows) {
  const d = one(r.fields['Session Date']) || 'Undated';
  (byDate[d] = byDate[d] || []).push({
    time:   `${one(r.fields['Session Start'])}-${one(r.fields['Session End'])}`,
    client: one(r.fields['Session Client']),
    role:   r.fields['Role'],
    staff:  one(r.fields['Staff Name']),
  });
}

let html = `<html><head><meta charset="utf-8"><style>
body{font-family:system-ui,sans-serif;margin:32px;color:#111}
h1{font-size:20px;margin-bottom:4px}
.sub{color:#666;font-size:12px;margin-bottom:24px}
h2{font-size:14px;margin:20px 0 6px;border-bottom:1px solid #ddd;padding-bottom:4px}
table{border-collapse:collapse;width:100%;font-size:13px}
td,th{text-align:left;padding:6px 10px;border-bottom:1px solid #eee}
th{background:#fafafa;font-weight:600}
</style></head><body>
<h1>Klaiya Live Schedule</h1>
<div class="sub">Generated ${new Date(Date.now() + 8*3600000).toISOString().slice(0,16).replace('T',' ')} PHT &middot; ${rows.length} assignments</div>`;

for (const date of Object.keys(byDate).sort()) {
  html += `<h2>${date}</h2><table><tr><th>Time</th><th>Client</th><th>Role</th><th>Staff</th></tr>`;
  for (const r of byDate[date].sort((a, b) => a.time.localeCompare(b.time))) {
    html += `<tr><td>${r.time}</td><td>${r.client}</td><td>${r.role}</td><td>${r.staff}</td></tr>`;
  }
  html += '</table>';
}
html += '</body></html>';

// convertToFile base64-DECODES its source property, so hand it base64.
return [{ json: {
  html: Buffer.from(html, "utf8").toString("base64"),
  assignmentCount: rows.length,
} }];

// RFC 5545 calendar feed - importable into Google Calendar,
// Outlook or Apple Calendar. Closes the "calendar sync" half of requirement 8.
// The Airtable node returns either { id, fields:{...} } or a flattened
// { id, ...fieldValues } depending on node version. Normalise both shapes.
const REC = (j) => (j && j.fields) ? j : { id: j && j.id, fields: j || {} };
const rows = $('Get Assignments').all().map(i => REC(i.json)).filter(r => r && r.id);
const one = (v) => Array.isArray(v) ? v[0] : v;

const stamp = new Date().toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
const fold = (s) => String(s).replace(/([,;\\])/g, '\\$1').replace(/\n/g, '\\n');

const lines = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Klaiya Digital Solution//Live Scheduling//EN',
  'CALSCALE:GREGORIAN',
  'METHOD:PUBLISH',
  'X-WR-CALNAME:Klaiya Live Schedule',
  'X-WR-TIMEZONE:Asia/Manila',
  'BEGIN:VTIMEZONE',
  'TZID:Asia/Manila',
  'BEGIN:STANDARD',
  'DTSTART:19700101T000000',
  'TZOFFSETFROM:+0800',
  'TZOFFSETTO:+0800',
  'TZNAME:PST',
  'END:STANDARD',
  'END:VTIMEZONE',
];

for (const r of rows) {
  const f = r.fields || {};
  const date = one(f['Session Date']);
  const start = one(f['Session Start']);
  const end = one(f['Session End']);
  if (!date || !start || !end) continue;

  const d = String(date).replace(/-/g, '');
  const t = (hhmm) => String(hhmm).replace(':', '') + '00';

  lines.push(
    'BEGIN:VEVENT',
    `UID:${r.id}@klaiya-scheduling`,
    `DTSTAMP:${stamp}`,
    `DTSTART;TZID=Asia/Manila:${d}T${t(start)}`,
    `DTEND;TZID=Asia/Manila:${d}T${t(end)}`,
    `SUMMARY:${fold(one(f['Session Client']) + ' - ' + f['Role'])}`,
    `DESCRIPTION:${fold('Staff: ' + one(f['Staff Name']) + '\nRole: ' + f['Role'] + '\nClient: ' + one(f['Session Client']))}`,
    `STATUS:${f['Status'] === 'Cancelled' ? 'CANCELLED' : 'CONFIRMED'}`,
    'BEGIN:VALARM',
    'TRIGGER:-PT60M',
    'ACTION:DISPLAY',
    'DESCRIPTION:Livestream session in 1 hour',
    'END:VALARM',
    'END:VEVENT',
  );
}

lines.push('END:VCALENDAR');

// convertToFile base64-DECODES its source property, so hand it base64.
return [{ json: {
  ics: Buffer.from(lines.join('\r\n'), "utf8").toString("base64"),
  eventCount: rows.length,
} }];
